    {'cat': 'remark', 'text': "Gaston. Un verre d'eau. Et vos observations.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_minuit_remark_35', 'whispered': False, 'nonverbal': False, 'gun': False, 'context': 'bar'},
    {'cat': 'remark', 'text': "Le barman entend tout. C'est le meilleur témoin de la soirée.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_minuit_remark_36', 'whispered': False, 'nonverbal': False, 'gun': False, 'context': 'bar'},
    {'cat': 'remark', 'text': 'Je ne trinque pas. Je regarde qui trinque avec qui.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_minuit_remark_37', 'whispered': False, 'nonverbal': False, 'gun': False, 'context': 'bar'},
    {'cat': 'remark', 'text': "Un cocktail qui porte le nom d'un naufrage. Personne ne trouve ça étrange ?", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_minuit_remark_38', 'whispered': False, 'nonverbal': False, 'gun': False, 'context': 'bar'},
    {'cat': 'remark', 'text': 'Allez, tout le monde sur la piste ! Ça va swinguer !', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_odette_remark_31', 'whispered': False, 'nonverbal': False, 'gun': False, 'context': 'dance'},
    {'cat': 'remark', 'text': "Aïe ! Toi, t'as deux pieds gauches, mon chou !", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_odette_remark_32', 'whispered': False, 'nonverbal': False, 'gun': False, 'context': 'dance'},
